CREATE TABLE "Flashcard" ("id" TEXT PRIMARY KEY, "front" TEXT NOT NULL, "back" TEXT NOT NULL, "dueAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "interval" INTEGER NOT NULL DEFAULT 0, "userId" TEXT NOT NULL REFERENCES "User"("id") ON DELETE CASCADE, "workspaceId" TEXT REFERENCES "Workspace"("id") ON DELETE SET NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Flashcard_userId_dueAt_idx" ON "Flashcard"("userId", "dueAt");
